import{_ as e,c as r,o,ae as t}from"./chunks/framework.CHDT0Kbg.js";const u=JSON.parse('{"title":"プライバシー設定","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/privacy-choices.md","filePath":"ja/guide/privacy-choices.md","lastUpdated":1795170900000}'),i={name:"ja/guide/privacy-choices.md"};function n(s,a,c,h,l,d){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="プライバシー設定" tabindex="-1">プライバシー設定 <a class="header-anchor" href="#プライバシー設定" aria-label="Permalink to &quot;プライバシー設定&quot;">​</a></h1><p>自分で管理するための簡単な方法。</p><h2 id="記録を残さずに-browsing" tabindex="-1">記録を残さずに browsing <a class="header-anchor" href="#記録を残さずに-browsing" aria-label="Permalink to &quot;記録を残さずに browsing&quot;">​</a></h2><p>プライベートウィンドウ（⌘⇧N）を使ってください。履歴やセッションに残らず、閉じるとタブは消えます。</p><h2 id="保存した内容を消す" tabindex="-1">保存した内容を消す <a class="header-anchor" href="#保存した内容を消す" aria-label="Permalink to &quot;保存した内容を消す&quot;">​</a></h2><p>設定の Cookie マネージャーから Cookie とサイトデータを削除できます。履歴やダウンロードも同じ場所で消去できます。</p><h2 id="サイトごとに許可を決める" tabindex="-1">サイトごとに許可を決める <a class="header-anchor" href="#サイトごとに許可を決める" aria-label="Permalink to &quot;サイトごとに許可を決める&quot;">​</a></h2><p>カメラ、マイク、ファイルのアクセスはサイトごとに記憶されます。設定で信頼するサイトを許可し、それ以外を拒否できます。ポップアップは許可したサイトだけに開かれます。</p><h2 id="バックグラウンド機能を制御する" tabindex="-1">バックグラウンド機能を制御する <a class="header-anchor" href="#バックグラウンド機能を制御する" aria-label="Permalink to &quot;バックグラウンド機能を制御する&quot;">​</a></h2><p>広告ブロックの購読は設定からいつでもオン・オフできます。オフにするとルールは取得されません。</p><h2 id="検索エンジンを選ぶ" tabindex="-1">検索エンジンを選ぶ <a class="header-anchor" href="#検索エンジンを選ぶ" aria-label="Permalink to &quot;検索エンジンを選ぶ&quot;">​</a></h2><p>設定で既定の検索エンジンを指定できます。検索候補は選択したエンジンから届きます。</p><h2 id="ご質問" tabindex="-1">ご質問 <a class="header-anchor" href="#ご質問" aria-label="Permalink to &quot;ご質問&quot;">​</a></h2><p>データの扱いについて詳しく知りたい場合は <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong> までご連絡ください。</p>',14)])])}const _=e(i,[["render",n]]);export{u as __pageData,_ as default};
